def berlekamp_massey(bits):
    # bits: list of 0/1, find minimal LFSR over GF(2): s[n] = sum c[i]*s[n-1-i]
    n=len(bits)
    C=[0]*(n+1); B=[0]*(n+1)
    L=0; m=-1; b=1
    for N in range(n):
        d=bits[N]
        for i in range(1,L+1):
            d^= C[i]&bits[N-i]
        if d==1:
            T=C[:]
            for i in range(0, n-m):
                if N-m+i < n+1: C[N-m+i]^= B[i]
            if L<=N//2:
                L=N+1-L; m=N; B=T
    return L, C[:L]
