        else { x ^= x>>a; x ^= x<<b; x ^= x>>c; }
        uint64_t y = M[mi]? x*M[mi] : x;
        double r = (double)(y>>s)*scale;
        if(fabs(r-R[i])>tol){ok=0;break;}
