{"command": "cd /tmp/t && cat > bf8.c <<'EOF'
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
static double R[40]; static int NR=0;
static inline int close(double r,double t){double d=r-t; if(d<0)d=-d; return d<=2.5e-17;}
int main(int argc,char**argv){
  FILE *f=fopen("rseq.json","r"); char buf[4096]; size_t n=fread(buf,1,sizeof buf,f); buf[n]=0; fclose(f);
  char *p=buf; while(*p&&*p!='[')++p;++p;
  while(*p!=']'){ R[NR++]=strtod(p,&p); while(*p&&(*p==' '||*p==','))++p; }
  int order=atoi(argv[1]),a=atoi(argv[2]),b=atoi(argv[3]),c=atoi(argv[4]);
  int steps = c?3:2;
  uint64_t m1=(uint64_t)(int)(R[0]*9007199254740992.0), m2=(uint64_t)(int)(R[1]*9007199254740992.0);
  uint64_t A0=m1<<11;
  uint64_t basis[11];
  for(int j=0;j<11;++j){ uint64_t x=1ULL<<j;
     if(order==0){ x^=x<<a; x^=x>>b; if(steps==3) x^=x<<c; } else { x^=x>>a; x^=x<<b; if(steps==3) x^=x>>c; }
     basis[j]=x>>11; }
  uint64_t xA=A0;
  if(order==0){ xA^=xA<<a; xA^=xA>>b; if(steps==3) xA^=xA<<c; } else { xA^=xA>>a; xA^=xA<<b; if(steps==3) xA^=xA>>c; }
  uint64_t target=m2 ^ (xA>>11);
  fprintf(stderr,"m1=%llu m2=%llu A0=%llx xA=%llx target=%llx\n",(unsigned long long)m1,(unsigned long long)m2,(unsigned long long)A0,(unsigned long long)xA,(unsigned long long)target);
  uint64_t w2[11]; uint32_t comb[11]; int n2=0; int pv2[11];
  for(int i=0;i<11;++i){ w2[i]=basis[i]; comb[i]=1u<<i; }
  for(int i=0;i<11;++i){ uint64_t cur=w2[i]; uint32_t cc=comb[i]; int hb;
     while(cur){ hb=63; while(!((cur>>hb)&1)) --hb;
        int k; for(k=0;k<n2;++k) if(pv2[k]==hb){ cur^=w2[k]; cc^=comb[k]; break; }
        if(k==n2) break; }
     if(!cur) continue;
     hb=63; while(!((cur>>hb)&1)) --hb;
     for(int k=0;k<n2;++k) if((w2[k]>>hb)&1){ w2[k]^=cur; comb[k]^=cc; }
     w2[n2]=cur; comb[n2]=cc; pv2[n2]=hb; ++n2;
  }
  uint64_t tg2=target; uint32_t sc=0;
  for(int k=0;k<n2;++k) if((tg2>>pv2[k])&1){ tg2^=w2[k]; sc^=comb[k]; }
  fprintf(stderr,"n2=%d tg2=%llx sc=%u\n",n2,(unsigned long long)tg2,sc);
  if(tg2==0){
     uint64_t x=A0^sc; int ok=1;
     for(int i=1;i<NR;++i){
        if(order==0){ x^=x<<a; x^=x>>b; if(steps==3) x^=x<<c; } else { x^=x>>a; x^=x<<b; if(steps==3) x^=x>>c; }
        if(!close((double)(x>>11)*(1.0/9007199254740992.0),R[i])){ok=0;break;}
     }
     fprintf(stderr,"ok=%d\n",ok);
  }
  return 0;
}
EOF
gcc -O2 -o bf8 bf8.c && cp rseq_test.json rseq.json && ./bf8 0 13 7 17; cp rseq_orig.json rseq.json"}

