#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include "rnglib.h"
static double R[40]; static int NR=0;
static inline int close(double r,double t){double d=r-t; if(d<0)d=-d; return d<=2.5e-17;}
static inline uint64_t T(uint64_t x,int order,int a,int b,int c,int steps){
  if(order==0){ x^=x<<a; x^=x>>b; if(steps==3) x^=x<<c; }
  else { x^=x>>a; x^=x<<b; if(steps==3) x^=x>>c; }
  return x;
}
int main(){
  FILE *f=fopen("rseq.json","r"); char buf[4096]; size_t n=fread(buf,1,sizeof buf,f); buf[n]=0; fclose(f);
  char *p=buf; while(*p&&*p!='[')++p;++p;
  while(*p!=']'){ R[NR++]=strtod(p,&p); while(*p&&(*p==' '||*p==','))++p; }
  long found=0;
  uint64_t m1=(uint64_t)(R[0]*9007199254740992.0), m2=(uint64_t)(R[1]*9007199254740992.0);
  uint64_t A0=m1<<11;
  for(int order=0;order<2;++order)
  for(int steps=2;steps<=3;++steps)
  for(int a=1;a<64;++a) for(int b=1;b<64;++b) for(int c=1;c<64;++c){
    breset();
    for(int j=0;j<11;++j) binsert(T(1ULL<<j,order,a,b,c,steps)>>11, 1u<<j);
    uint64_t target = m2 ^ (T(A0,order,a,b,c,steps)>>11);
    uint32_t e;
    if(breduce(target,&e)){
      uint64_t x=A0^e; int ok=1;
      for(int i=1;i<NR;++i){
        x=T(x,order,a,b,c,steps);
        if(!close((double)(x>>11)*(1.0/9007199254740992.0),R[i])){ok=0;break;}
      }
      if(ok){printf("MATCH order=%d steps=%d a=%d b=%d c=%d e=%u\n",order,steps,a,b,c,e);++found; fflush(stdout);}
    }
  }
  fprintf(stderr,"TOTAL found=%ld\n",found);
  return 0;
}
