import random, subprocess
random.seed(44)
alpha="ACGTacgtN#KMRkmrSWYswyVDBHvdbh"
flags=['-c','-S','-V','-x','-1','-2','-C','-U','-r','-R','-N','-a','-A']
def mk(i, fastq):
    L=random.randint(1,40)
    s=''.join(random.choice(alpha) for _ in range(L))
    name='r%d'%i
    if fastq: return '@%s c%d\n%s\n+\n%s\n'%(name,i,s,'I'*L)
    return '>%s c%d\n%s\n'%(name,i,s)
def run(opts, f):
    r=subprocess.run(['/workspace/executable','seq']+opts+[f],capture_output=True,input=b'',cwd='/tmp/t')
    return r.stdout.decode()
diffs={}
for fl in flags:
    diffs[fl]=0
for t in range(60):
    for fastq in (False,True):
        lines=''.join(mk(i,fastq) for i in range(3))
        ext='.fq' if fastq else '.fa'
        open('/tmp/t/y'+ext,'w').write(lines)
        base=run([], '/tmp/t/y'+ext)
        for fl in flags:
            o=run([fl], '/tmp/t/y'+ext)
            if o!=base:
                diffs[fl]+=1
                if diffs[fl]<3: print("DIFF",fl,ext,repr(base[:60]),repr(o[:60]))
print(diffs)
EOF"}

