		if (skip_N) { int has = 0; for (i = 0; i < ks->seq.l; ++i) if (ks->seq.s[i]=='N'||ks->seq.s[i]=='n') has = 1; if (has) continue; }
		if (mask_char || q != 20 || qoff != 33) { }
