	case 'A': return "T"; case 'T': return "A"; case 'a': return "t"; case 't': return "a";
	case 'C': return "G"; case 'G': return "C"; case 'c': return "g"; case 'g': return "c";
	case 'K': return "M"; case 'M': return "K"; case 'k': return "m"; case 'm': return "k";
	case 'R': return "Y"; case 'Y': return "R"; case 'r': return "y"; case 'y': return "r";
	case 'S': return "S"; case 's': return "s"; case 'W': return "W"; case 'w': return "w";
	case 'D': return "H"; case 'H': return "D"; case 'd': return "h"; case 'h': return "d";
	case 'B': return "V"; case 'V': return "B"; case 'b': return "v"; case 'v': return "b";
	case 'U': return "A"; case 'u': return "a";
	default: return 0;
	}
}
static inline int is_base_c(int c){ return c=='A'||c=='a'; }
static inline int is_Cish(int c){ return c=='C'||c=='c'||c=='Y'||c=='y'; }
static inline int is_Gish(int c){ return c=='G'||c=='g'||c=='R'||c=='r'; }
static inline int is_het2(int c){ return strchr("KkMmRrSsWwYy", c) && c; }
static inline int is_het3(int c){ return strchr("VvDdBbHh", c) && c; }
static inline int is_KMWS(int c){ return strchr("KkMmWwSs", c) && c; }
static inline int is_RY(int c){ return strchr("RrYy", c) && c; }

/* ---------- RNG (unidentified; placeholder xorshift64*) ---------- */
static u64i_t seq_rand_state = 11;
static inline u64i_t seq_rand_next(void)
{
	u64i_t x = seq_rand_state;
	x ^= x >> 12; x ^= x << 25; x ^= x >> 27;
	seq_rand_state = x;
	return x * 2685821657736338717ULL;
}
static inline double seq_drand(void) { return (double)(seq_rand_next() >> 11) * (1.0/9007199254740992.0); }

/* ---------- main_seq ---------- */
static void print_folded(const char *s, size_t l, long ll)
{
	size_t i;
	if (ll <= 0) { fwrite(s, 1, l, stdout); putchar('\n'); return; }
	for (i = 0; i < l; i += (size_t)ll) { fwrite(s+i, 1, (l-i < (size_t)ll)? l-i : (size_t)ll, stdout); putchar('\n'); }
	if (l == 0) putchar('\n');
}
static void emit_record(kseq_t *ks, int to_fasta, const char *fake_q, const char *comment_out, long ll, char strand)
{
	size_t i;
	if (strand) printf("%c%s", strand, ks->name.s);
	else printf("%s", ks->name.s);
	if (comment_out && ks->comment.l) { fwrite(ks->comment.s, 1, ks->comment.l, stdout); }
	putchar('\n');
	print_folded(ks->seq.s, ks->seq.l, ll);
	if (!to_fasta) {
		const char *q = fake_q ? fake_q : ks->qual.s;
		size_t ql = fake_q ? ks->seq.l : ks->qual.l;
		if (ql) { putchar('+'); putchar('\n'); print_folded(q, ql, ll); }
	}
}

static int stk_seq(int argc, char *argv[])
{
	int c, opt;
	int to_fasta = 0, no_comment = 0, rev_comp = 0, both = 0, upper = 0, skip_N = 0;
	int sel = 0;
	long ll = 0, min_len = 0;
	double q = 20, frac = 0;
	long qoff = 33;
	char mask_char = 0, fake_q = 0;
	const char *regfile = 0;
	long seed = 11;
	kseq_t *ks;
	while ((opt = getopt(argc, argv, "acrl:n:q:s:f:xCARNSUV12l:L:M:Q:F:X:")) != -1) {
		switch (opt) {
		case 'a': case 'A': to_fasta = 1; break;
		case 'C': no_comment = 1; break;
		case 'U': upper = 1; break;
		case 'r': rev_comp = 1; break;
		case 'R': both = 1; break;
		case 'N': skip_N = 1; break;
		case 'c': case 'S': case 'V': case 'x': break;
		case '1': sel = 1; break;
		case '2': sel = 2; break;
		case 'l': ll = atol(optarg); break;
		case 'L': min_len = atol(optarg); break;
		case 'n': mask_char = optarg[0]; break;
		case 'q': q = atof(optarg); break;
		case 'Q': qoff = atol(optarg); break;
		case 'M': regfile = optarg; break;
		case 'F': fake_q = optarg[0]; break;
		case 'f': frac = atof(optarg); break;
		case 's': seed = atol(optarg); break;
		case 'X': break;
		default: return 1;
		}
	}
	seq_rand_state = (u64i_t)seed;
	ks = kseq_init(optind < argc ? argv[optind] : 0);
	if (ks->f == 0) { fprintf(stderr, "[E::stk_seq] failed to open the input file/stream.\n"); return 1; }
	while (kseq_read(ks) >= 0) {
		size_t i;
		if (sel == 1 && (ks->name.l) ) { }
		if (min_len > 0 && (long)ks->seq.l < min_len) continue;
		if (skip_N) { int has = 0; for (i = 0; i < ks->seq.l; ++i) if (ks->seq.s[i]=='N'||ks->seq.s[i]=='n') has = 1; if (has) continue; }
		if (mask_char || q != 20 || qoff != 33) { }
		if (qoff != 33 || q != 20) {
			for (i = 0; i < ks->seq.l; ++i) {
				int qq = (int)(unsigned char)ks->qual.s[i] - (int)qoff;
				if (ks->qual.l && qq < (int)q) ks->seq.s[i] = mask_char ? mask_char : (char)tolower((unsigned char)ks->seq.s[i]);
			}
		}
		if (upper) for (i = 0; i < ks->seq.l; ++i) ks->seq.s[i] = (char)toupper((unsigned char)ks->seq.s[i]);
		if (rev_comp) {
			for (i = 0; i < ks->seq.l/2; ++i) {
				char a = ks->seq.s[i], b = ks->seq.s[ks->seq.l-1-i];
				const char *ca = comp_table(a), *cb = comp_table(b);
				ks->seq.s[i] = cb ? cb[0] : b;
				ks->seq.s[ks->seq.l-1-i] = ca ? ca[0] : a;
			}
			if (ks->seq.l & 1) { char m = ks->seq.s[ks->seq.l/2]; const char *cm = comp_table(m); if (cm) ks->seq.s[ks->seq.l/2] = cm[0]; }
			for (i = 0; i < ks->qual.l/2; ++i) { char t = ks->qual.s[i]; ks->qual.s[i] = ks->qual.s[ks->qual.l-1-i]; ks->qual.s[ks->qual.l-1-i] = t; }
		}
		if (to_fasta) emit_record(ks, 1, 0, no_comment?0:ks->comment.s, ll, 0);
		else if (fake_q) emit_record(ks, 0, &fake_q, no_comment?0:ks->comment.s, ll, 0);
		else if (ks->qual.l) emit_record(ks, 0, 0, no_comment?0:ks->comment.s, ll, 0);
		else emit_record(ks, 1, 0, no_comment?0:ks->comment.s, ll, 0);
		if (both) {
			/* reverse complement copy */
			kstr_t sq; sq.s = (char*)malloc(ks->seq.l+1); memcpy(sq.s, ks->seq.s, ks->seq.l);
			kstr_t qq; qq.s = (char*)malloc(ks->qual.l+1); memcpy(qq.s, ks->qual.s, ks->qual.l);
			size_t l2 = ks->seq.l;
			for (i = 0; i < l2; ++i) { const char *cc = comp_table(sq.s[l2-1-i]); sq.s[i] = cc ? cc[0] : sq.s[l2-1-i]; }
			for (i = 0; i < ks->qual.l/2; ++i) { char t = qq.s[i]; qq.s[i] = qq.s[ks->qual.l-1-i]; qq.s[ks->qual.l-1-i] = t; }
			kstr_t sn; sn.s = strdup(ks->name.s); sn.l = ks->name.l;
			kstr_t sc; sc.s = strdup(ks->comment.s); sc.l = ks->comment.l;
			kstr_t s1; s1.s = sq.s; s1.l = l2;
			kstr_t q1; q1.s = qq.s; q1.l = ks->qual.l;
			{ kseq_t tmp; tmp = *ks; tmp.seq = s1; tmp.qual = q1; tmp.name = sn; tmp.comment = sc;
			  emit_record(&tmp, to_fasta, 0, no_comment?0:sc.s, ll, '-'); }
			free(sq.s); free(qq.s); free(sn.s); free(sc.s);
		}
	}
	kseq_destroy(ks);
	return 0;
}

static int stk_size(int argc, char *argv[])
{
	kseq_t *ks; long n = 0, b = 0;
	ks = kseq_init(optind < argc ? argv[optind] : 0);
	if (ks->f == 0) { fprintf(stderr, "[E::stk_size] failed to open the input file/stream.\n"); return 1; }
	while (kseq_read(ks) >= 0) { ++n; b += (long)ks->seq.l; }
	printf("%ld\t%ld\n", n, b);
	kseq_destroy(ks);
	return 0;
}

static int stk_comp(int argc, char *argv[])
{
	int opt, uflag = 0;
	kseq_t *ks;
	while ((opt = getopt(argc, argv, "r:u")) != -1) {
		switch (opt) { case 'r': break; case 'u': uflag = 1; break; default: return 1; }
	}
	ks = kseq_init(optind < argc ? argv[optind] : 0);
	if (ks->f == 0) { fprintf(stderr, "[E::stk_comp] failed to open the input file/stream.\n"); return 1; }
	while (kseq_read(ks) >= 0) {
		long cnt[5] = {0,0,0,0,0};
		long het2 = 0, het3 = 0, c8 = 0, c9 = 0, c10 = 0, c11 = 0;
		size_t i;
		#define CNT(x) (uflag ? (isupper((unsigned char)(x))?1:0) : 1)
		for (i = 0; i < ks->seq.l; ++i) {
			int ch = (unsigned char)ks->seq.s[i];
			switch (ch) {
			case 'A': case 'a': cnt[0] += CNT(ch); break;
			case 'C': case 'c': cnt[1] += CNT(ch); break;
			case 'G': case 'g': cnt[2] += CNT(ch); break;
			case 'T': case 't': cnt[3] += CNT(ch); break;
			default:
				if (ch=='+'||ch=='>'||ch=='@') break;
				if (is_het2(ch)) { het2 += CNT(ch); if (is_KMWS(ch)) c9 += CNT(ch); else c10 += CNT(ch); }
				else if (is_het3(ch)) het3 += CNT(ch);
				else cnt[4] += CNT(ch);
				break;
			}
		}
		for (i = 0; i + 1 < ks->seq.l; ++i) {
			int a = (unsigned char)ks->seq.s[i], b = (unsigned char)ks->seq.s[i+1];
			if (is_Cish(a) && is_Gish(b)) {
				c8 += CNT(a) + CNT(b);
				if (a=='Y'||a=='y') c11 += CNT(a);
				if (b=='R'||b=='r') c11 += CNT(b);
			}
		}
		#undef CNT
		printf("%s\t%ld", ks->name.s, (long)ks->seq.l);
		{ int j; for (j = 0; j < 5; ++j) printf("\t%ld", cnt[j]); }
		printf("\t%ld\t%ld\t%ld\t%ld\t%ld\t%ld\n", het2, het3, c8, c9, c10, c11);
	}
	kseq_destroy(ks);
	return 0;
}
CEOF
